      getItemsMany: () => Promise.resolve([])
    },
    fetch: (u) => {
      calls.push(['fetch', String(u)]);
      const cats = s.cats.map((c) => ({ id: c.id, name: c.name, icon: c.icon, achievements: Object.keys(s.achToCat).filter((k) => s.achToCat[k] === String(c.id)).map(Number) }));
